\label{thm:intro-self-testing}
For \(n=2m\), consider a finite-dimensional strategy for the Grothendieck game $G_n$ with state \(|{\psi}\rangle\) and observables \(A(x),B(y)\) for $x,y \in S^{n-1}$. If the strategy achieves bias at least \((1-\varepsilon)\beta_\mathrm{q}(G_n)\), then there exist local isometries \(\Phi_A,\Phi_B\) and an auxiliary state
\(|{\mathrm{aux}}\rangle\) such that 
    \begin{align*}
        \norm[\big]{(\Phi_A \otimes \Phi_B)|{\psi}\rangle - |{\psi^+_{2^m}}\rangle \otimes |{\mathrm{aux}}\rangle}^2 &\leq \operatorname{{O}}(n^2\varepsilon), \\
        \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm[\big]{ ((\Phi_A A(x) - (\gamma(x) \otimes I)\Phi_A) \otimes I)|{\psi}\rangle}^2 &\leq \operatorname{{O}}(n\varepsilon), \\
        \operatorname*{\mathbb{E}}_{y \sim \sigma_n} \norm[\big]{ (I\otimes (\Phi_B B(y) - (\overline{\gamma(y)} \otimes I)\Phi_B))|{\psi}\rangle}^2 &\leq \operatorname{{O}}(n\varepsilon)
    \end{align*}
where \(|{\psi^+_{2^m}}\rangle\) is the $2^m$-dimensional maximally entangled state.

\label{thm:intro-spinselftest}
In the situation of \cref{thm:intro-self-testing}, we also have (for the same local isometries and state):
    \begin{align*}
        \operatorname*{\mathbb{E}}_{R \in \mathrm{SO}(n)} \operatorname*{\mathbb{E}}_{g \in \operatorname{Pin}(n)} \norm[\big]{((\Phi_A A_R(g) - (\Gamma(g) \otimes I)\Phi_A) \otimes I)|{\psi}\rangle}^2 &\leq \operatorname{{O}}(n^3 \varepsilon), \\
        \operatorname*{\mathbb{E}}_{R \in \mathrm{SO}(n)} \operatorname*{\mathbb{E}}_{g \in \operatorname{Pin}(n)} \norm[\big]{(I \otimes (\Phi_B B_R(g) - (\overline{\Gamma(g)}\otimes I)\Phi_B))|{\psi}\rangle}^2 &\leq \operatorname{{O}}(n^3 \varepsilon).
    \end{align*}

A \emph{classical strategy} \(S=(a,b)\) for an XOR game \({G}\) consists of
    \begin{itemize}
        \item a probability space \((\Omega, \mathcal{F}, \nu)\) describing shared randomness independent of the questions, along with
        \item a family of deterministic strategies \(\set{(a_w,b_w)}_{w\in \Omega}\) such that the maps \((w,x) \mapsto a_w(x)\) and \((w,y) \mapsto b_w(y)\) are jointly measurable.
    \end{itemize}

A \emph{quantum strategy} \(S=(A,B,|{\psi}\rangle)\) for an XOR game \({G}\) consists of
    \begin{itemize}
        \item a pure quantum state \(|{\psi}\rangle \in \mathcal{H}_A \otimes \mathcal{H}_B\) in the tensor product of two finite-dimensional Hilbert spaces \(\mathcal{H}_A\) and \(\mathcal{H}_B\),
        \item measurable functions $A \colon \mathcal X \to \mathrm U(\mathcal H_A)$ and $B \colon \mathcal Y \to \mathrm U(\mathcal H_B)$ satisfying \(A(x)^2 = B(y)^2 = I\) for all $x \in \mathcal X$ and $y \in \mathcal Y$.
    \end{itemize}

\label{thm:vectorupperbound}
For the vector bias $\beta_\mathrm{vec}(G_n)$ it holds that
\begin{align*}
    \beta_\mathrm{vec}(G_n) = \frac 1{nz_n},
\end{align*}
where $z_n$ is given in \Cref{def:zn}.

\label{lem:sphere-moments}
    It holds that
    \begin{align*}
          \operatorname*{\mathbb{E}}_{x \sim \sigma_n} [x_i^4] &= \frac{3}{n(n+2)}, \quad \operatorname*{\mathbb{E}}_{x \sim \sigma_n}[x_i^2 x_j^2] = \frac{1}{n(n+2)} &&\text{ for \(i \neq j\)}\\
        \operatorname*{\mathbb{E}}_{x \sim \sigma_n} x_i^6 &= \frac{15}{n(n+2)(n+4)}, \quad \operatorname*{\mathbb{E}}_{x \sim \sigma_n} x_i^4 x_j^2 = \frac{3}{n(n+2)(n+4)} &&\text{ for }i\neq j,\\
        \operatorname*{\mathbb{E}}_{x \sim \sigma_n} x_i^2x_j^2x_k^2 &= \frac{1}{n(n+2)(n+4)} &&\text{ for } i \neq j \neq k \neq i.
    \end{align*}

\label{thm:vector-rigidity}
    Let \(N \geq n\) and \(\varepsilon \geq 0\).
    Consider an \(\varepsilon\)-optimal vector strategy \(S = (a,b)\) for the Grothendieck game~\(G_n\).
    Then there exists an isometry \(V \colon \mathbb R^n \to \mathbb R^N\) such that 
    \begin{align*}
        \operatorname*{\mathbb{E}}_{x\sim \sigma_n} \norm*{a(x) - V x}^2 + \operatorname*{\mathbb{E}}_{y\sim\sigma_n} \norm*{b(y) - V y}^2
        \leq (20\sqrt5n +2)\varepsilon
        = \operatorname{{O}}(n\varepsilon).
    \end{align*}

Let \(n \geq 3\), and let \(Q \colon \mathbb R^n \to \mathbb R^n\) be the orthogonal projection onto the first \(n-2\) coordinates.
We use the normalized projection strategy from \cite[Lemma~4]{briet2011generalized}:
\begin{equation}\label{eq:projection-strategy}
    a(x) = b(x) = \frac{Qx}{\norm{Qx}}, \quad Qx \neq 0
\end{equation}
and set \(a(x) = b(x) = e_1\) on the null set where \(Qx = 0\).

By \cite[Equation~(27)]{briet2011generalized}, with \(k = n-2\),
\[
    \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm{Qx} = \frac{n-2}{n-1}.
\]
Coordinate reflections and symmetry among the first \(n-2\) coordinates therefore give
\begin{equation}\label{eq:optimality-self-testing}
    \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \frac{x_j x_k}{\norm{Qx}} = \frac{\delta_{j,k}}{n-2}\operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm{Qx} = 
    \frac{\delta_{j,k}}{n-1} ,\quad 1 \leq j \leq n-2, 1 \leq k \leq n
\end{equation}
where the quotient is defined to be zero when \(Qx = 0\).
It follows that \(T_a = T_b = Q/(n-1)\), and hence
\begin{equation}\label{eq:projection-bias}
    \beta(G_n, (a,b)) = \frac{n-2}{z_n(n-1)^2} = \frac{1}{nz_n} \left( 1 - \frac{1}{(n-1)^2}\right).
\end{equation}
Thus, this strategy is \((n-1)^{-2}\)-optimal.

    For every isometry \(V\colon\mathbb R^n\to\mathbb R^n\), we have
    \begin{align*}
    \operatorname*{\mathbb{E}}_{x\sim\sigma_n}\norm{a(x)-Vx}^2
    +\operatorname*{\mathbb{E}}_{y\sim\sigma_n}\norm{b(y)-Vy}^2
    &=4-4\left\langle T_a,V\right\rangle_{\mathrm{HS}}
    =4-\frac{4}{n-1}
      \sum_{j=1}^{n-2}\left\langle e_j,Ve_j\right\rangle\\
    &\geq\frac{4}{n-1},
\end{align*}
where equality holds for \(V=I\).
Hence, any uniform upper bound \(f(n)\varepsilon\)
must satisfy \(\frac{4}{n-1}\leq\frac{f(n)}{(n-1)^2}\) proving \(f(n)=\Omega(n)\).

\label{lem:state-dependent-seminorm}
    Let \(\rho\) be a density operator on \(\mathcal H\) and consider linear operators \(T_1, \dots, T_n \colon \mathcal H \to \mathcal K\). It holds
    \begin{equation}\label{eq:seminorm-sphere}
        \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm*{ \sum_{i = 1}^n x_i T_i}_\rho^2 = \frac 1n \sum_{i= 1}^n \norm{T_i}_\rho^2
    \end{equation}

From \(\operatorname*{\mathbb{E}}_{x \sim \sigma_n} x_i x_j = \delta_{i,j}/n\), we obtain
    \begin{align*}
        \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm*{ \sum_{i = 1}^n x_i T_i}_\rho^2 &= \sum_{i,j = 1}^n\operatorname*{\mathbb{E}}_{x \sim \sigma_n} x_ix_j \operatorname{tr}[T_i^\dagger T_j\rho] = \frac 1n \sum_{i = 1}^n \norm{T_i}_\rho^2.
    \end{align*}

\label{lemma:average-clifford-relations}
    Let \(n \geq 2\) and let \( 0 \leq \varepsilon < 1\).
    Consider an \(\varepsilon\)-optimal quantum strategy \( S =(A,B, |{\psi}\rangle)\) for the Grothendieck game~\(G_n\).
    Then the following averaged consistency and anticommutation bounds hold:
    \begin{align}
        \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm{(A(x) \otimes I - I \otimes B(x))|{\psi}\rangle}^2 &\leq \operatorname{{O}}(\varepsilon)\label{eq:consistency} \\
        \operatorname*{\mathbb{E}}_{x \perp y} \paren*{\norm{\{A(x),A(y)\}}_{\rho_A}^2 + \norm{\{B(x),B(y)\}}_{\rho_B}^2}  &\leq \operatorname{{O}}(\varepsilon) \label{eq:anti-commutation}
    \end{align}
    where \(\operatorname*{\mathbb{E}}_{x \perp y}\) denotes expectation over a Haar-random ordered orthonormal pair~\((x,y)\).

Let \(L\) be the map from \cref{lem:common-linear-map}.
    The triangle inequality and the bound in \cref{lem:common-linear-map} give
    \begin{align*}
        \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm{(A(x) \otimes I - I \otimes B(x))|{\psi}\rangle}^2 &\leq 2 \operatorname*{\mathbb{E}}_{x \sim \sigma_n}\paren*{ \norm{(A(x) \otimes I)|{\psi}\rangle - Lx}^2 + \norm{(I \otimes B(x))|{\psi}\rangle - Lx}^2} \\
        &\leq 4\varepsilon.
    \end{align*}

    To prove the anticommutation bound, fix an orthonormal pair \((x,y)\) and set \(z \coloneq \frac{x+y}{\sqrt 2}\).
    By \Cref{eq:seminorm-purification}, the triangle inequality, and linearity of \(L\),
    \begin{align*}
        \norm*{A(z) - \frac{A(x)+ A(y)}{\sqrt 2}}_{\rho_A}
        &\leq \norm{(A(z) \otimes I)|{\psi}\rangle - L z} + \frac{1}{\sqrt 2} \norm{(A(x) \otimes I)|{\psi}\rangle - Lx} \\
        &\quad + \frac{1}{\sqrt 2} \norm{(A(y) \otimes I)|{\psi}\rangle - Ly}
    \end{align*}
    with an analogous bound for Bob.
    By rotational invariance, each of\(x,y,z\) has marginal distribution \(\sigma_n\).
    Squaring the preceding bound, using \((a+b+c)^2 \leq 3a^2 + 3b^2 + 3c^2\), and applying \cref{lem:common-linear-map} therefore gives
    \begin{equation}\label{eq:approx-linearity}
        \operatorname*{\mathbb{E}}_{x \perp y} \paren*{
        \norm*{A(z) - \frac{A(x) + A(y)}{\sqrt 2}}_{\rho_A}^2 + \norm*{B(z) - \frac{B(x) + B(y)}{\sqrt 2}}_{\rho_B}^2} \leq 12\varepsilon.
    \end{equation}

    We next express the anticommutator errors in terms of consistency and linearity errors.
    The identity
    \begin{multline*}
        \{A(x),A(y)\} \otimes I = (A(x) \otimes B(y) + A(y) \otimes B(x)) \\+ (A(x) \otimes I)(A(y) \otimes I - I \otimes B(y)) + (A(y) \otimes I)(A(x) \otimes I - I \otimes B(x)),
    \end{multline*}
    together with \Cref{eq:seminorm-purification}, the triangle inequality, and the fact that observables have operator norm at most \(1\), gives
    \begin{multline}
        \norm{\{A(x), A(y)\}}_{\rho_A} \leq \norm{(A(x) \otimes B(y) + A(y) \otimes B(x))|{\psi}\rangle} \\+ \norm{(A(x) \otimes I - I \otimes B(x))|{\psi}\rangle} + \norm{(A(y) \otimes I - I \otimes B(y))|{\psi}\rangle} \label{eq:ac-1}.
    \end{multline}
    Similarly, the identity
    \begin{multline*}
    A(x) \otimes B(y) + A(y) \otimes B(x) = 2\paren*{\frac{A(x) + A(y)}{\sqrt 2} \otimes \frac{B(x) + B(y)}{\sqrt 2} - I} \\
    + (A(x) \otimes I)(A(x) \otimes I - I \otimes B(x))+ (A(y) \otimes I)(A(y) \otimes I - I \otimes B(y))
    \end{multline*}
    and the triangle inequality bound the first term on the right-hand side of \Cref{eq:ac-1} by
    \begin{multline}
        \norm{(A(x) \otimes B(y) + A(y) \otimes B(x))|{\psi}\rangle} \leq 2 \norm*{\paren*{\paren*{\frac{A(x) + A(y)}{\sqrt 2} \otimes \frac{B(x) + B(y)}{\sqrt 2}} - I}|{\psi}\rangle}\\ + \norm{(A(x) \otimes I - I \otimes B(x))|{\psi}\rangle}  + \norm{(A(y) \otimes I - I \otimes B(y))|{\psi}\rangle}\label{eq:ac-2}.
    \end{multline}
    Further, by the triangle inequality we can upper-bound the first term of the right-hand side of \Cref{eq:ac-2} by
    \begin{multline}
        \norm*{\paren*{\paren*{\frac{A(x) + A(y)}{\sqrt 2} \otimes \frac{B(x) + B(y)}{\sqrt 2}} - I}|{\psi}\rangle} \leq\norm*{\paren*{\paren*{\frac{A(x) + A(y)}{\sqrt 2} - A(z)} \otimes \frac{B(x) + B(y)}{\sqrt 2}}|{\psi}\rangle} \\
        + \norm*{\paren*{A(z) \otimes \paren*{\frac{B(x) + B(y)}{\sqrt 2} - B(z)}}|{\psi}\rangle} + \norm{(A(z) \otimes I)(A(z) \otimes I - I \otimes B(z))|{\psi}\rangle}\label{eq:ac-3}.
    \end{multline}
    The same estimates hold with Alice and Bob interchanged.
    Combining \Cref{eq:ac-1,eq:ac-2,eq:ac-3}, using \linebreak\(\norm*{\frac{P(x)+P(y)}{\sqrt 2}} \leq \sqrt 2\) for \(P \in \{A,B\}\), using Cauchy--Schwarz, and taking expectations, we get
    \[
        \operatorname*{\mathbb{E}}_{x \perp y} \paren*{ \norm*{ \{A(x),A(y)\}}_{\rho_A}^2 + \norm*{\{B(x),B(y)\}}_{\rho_B}^2 }\leq \operatorname{{O}}(\varepsilon).
    \]

Set $Q_j=\frac{I+R_j}{2}$, $v_{k+1}=|{\phi}\rangle$ and $v_j=Q_jv_{j+1}$. Decompose
\[ 
2|{\phi}\rangle-v_j =Q_j(2|{\phi}\rangle-v_{j+1})+2(I-Q_j)|{\phi}\rangle 
\]
into two orthogonal vectors. Since the vectors are orthogonal, it holds $\|Q_j\|\leq 1$ and $2(I-Q_j)=I-R_j$, we get
\begin{align}
 \|2|{\phi}\rangle-v_j\|^2 &=\|Q_j(2|{\phi}\rangle-v_{j+1})\|^2+\|2(I-Q_j)|{\phi}\rangle\|^2\nonumber\\ 
&\le \|2|{\phi}\rangle-v_{j+1}\|^2+\|(R_j-I)|{\phi}\rangle\|^2.\label{eq:vecbound}
\end{align}
Summing over $j$ in \Cref{eq:vecbound} and using $\||{\phi}\rangle\| = 1$ gives
\begin{align}
\|2|{\phi}\rangle-v_1\|^2 \le 1+\sum_j\|(R_j-I)|{\phi}\rangle\|^2.\label{eq:vecbound2} 
\end{align}
It holds $\frac12\sum_{a_j\in\{0,1\}}R_j^{a_j} = \frac{I+R_j}{2}=Q_j$ and therefore
\[ \mathbb E_{a\in\{0,1\}^k} R_1^{a_1}\cdots R_k^{a_k}|{\phi}\rangle=Q_1\cdots Q_k|{\phi}\rangle=v_1. \]
Since each $R_1^{a_1}\cdots R_k^{a_k}$ is unitary and by \Cref{eq:vecbound2}, we obtain
\begin{align*}
 \mathbb E_a\|(R_1^{a_1}\cdots R_k^{a_k}-I)|{\phi}\rangle\|^2 &=2-2\operatorname{Re}\langle{\phi}|v_1\rangle\\ 
&=\|2|{\phi}\rangle-v_1\|^2-1-\||{\phi}\rangle-v_1\|^2\\ 
&\le \sum_j\|(R_j-I)|{\phi}\rangle\|^2.
\end{align*}

\label{thm:self-testing}
    Let \(m \geq 1\) be an integer, \(0 \leq \varepsilon < 1\), and set \(n = 2m\).
    Consider an \(\varepsilon\)-optimal quantum strategy \(S = (A,B,|{\psi}\rangle) \) for the Grothendieck game~\(G_n\).
    Then there exist local isometries \( \Phi_A \colon \mathcal{H}_A \to (\mathbb C^2)^{\otimes m} \otimes \mathcal{H}_{A, \mathrm{aux}}\), \(\Phi_B \colon \mathcal{H}_B \to (\mathbb C^2)^{\otimes m} \otimes \mathcal{H}_{B, \mathrm{aux}}\), and a state \(|{\mathrm{aux}}\rangle \in \mathcal{H}_{A, \mathrm{aux}} \otimes \mathcal{H}_{B, \mathrm{aux}}\) such that
    \begin{align*}
        \norm[\big]{(\Phi_A \otimes \Phi_B)|{\psi}\rangle - |{\psi^+_{2^m}}\rangle \otimes |{\mathrm{aux}}\rangle}^2 &\leq \operatorname{{O}}(n^2\varepsilon), \\
        \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm[\big]{ \Phi_A A(x) - (\gamma(x) \otimes I)\Phi_A}_{\rho_A}^2 &\leq \operatorname{{O}}(n\varepsilon), \\
        \operatorname*{\mathbb{E}}_{y \sim \sigma_n} \norm[\big]{\Phi_B B(y) - (\overline{\gamma(y)} \otimes I)\Phi_B}_{\rho_B}^2 &\leq \operatorname{{O}}(n\varepsilon).
    \end{align*}

\label{cor:HighProb}
    Let \(n = 2m \geq 2\) be even, let \(0 \leq \varepsilon< 1\), and let \( 0 < \delta < 1\).
    Fix an \(\varepsilon\)-optimal quantum strategy \(S = (A,B,|{\psi}\rangle)\) for the Grothendieck game \(G_n\), and let \(Q = (q_1, \dots, q_n)\) be a Haar-random orthonormal basis of \(\mathbb R^n\).
    Then with probability at least \(1-\delta\), there exist local isometries \(\Psi_A^Q \colon \mathcal{H}_A \to (\mathbb C^2)^{\otimes m} \otimes \mathcal H_{A,\mathrm{aux}}, \Psi_B^Q \colon \mathcal{H}_B \to (\mathbb C^2)^{\otimes m} \otimes \mathcal H_{B, \mathrm{aux}}\), and a state \(|{\mathrm{aux}}\rangle\in \mathcal{H}_{A,\mathrm{aux}} \otimes \mathcal{H}_{B, \mathrm{aux}} \) such that
    \begin{align*}
        \norm*{ (\Psi_A^Q \otimes \Psi_B^Q)|{\psi}\rangle - |{\psi_{2^m}^+}\rangle\otimes |{\mathrm{aux}}\rangle}^2 &\leq \operatorname{{O}}(n^2\varepsilon)
    \end{align*}
    and, for every \(i \in [n]\),
    \begin{align*}
        \norm*{\Psi_A^Q A(q_i) - (\gamma_i \otimes I)\Psi_A^Q}_{\rho_A}^2 &\leq \operatorname{{O}}(n^2\varepsilon/\delta), \\
        \norm*{\Psi_B^Q B(q_i) - (\overline{\gamma_i} \otimes I)\Psi_B^Q}_{\rho_B}^2 &\leq \operatorname{{O}}(n^2\varepsilon/\delta).
    \end{align*}

\label{thm:spinselftest}
In the situation of \cref{thm:self-testing}, we also have (for the same local isometries and state):
    \begin{align*}
        \operatorname*{\mathbb{E}}_{R \in \mathrm{SO}(n)} \operatorname*{\mathbb{E}}_{g \in \operatorname{Pin}(n)} \norm*{\Phi_A A_R(g) - (\Gamma(g) \otimes I)\Phi_A}_{\rho_A}^2 &\leq \operatorname{{O}}(n^3 \varepsilon), \\
        \operatorname*{\mathbb{E}}_{R \in \mathrm{SO}(n)} \operatorname*{\mathbb{E}}_{g \in \operatorname{Pin}(n)} \norm*{\Phi_B B_R(g) - (\overline{\Gamma(g)}\otimes I)\Phi_B}_{\rho_B}^2 &\leq \operatorname{{O}}(n^3 \varepsilon).
    \end{align*}

We only prove the first inequality; the second one is completely analogous.
First note that the second estimate in \cref{thm:self-testing} reads:
\begin{align}\label{eq:bound 1}
    \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm*{\Phi_A A(x) - (\gamma(x) \otimes I)\Phi_A}_{\rho_A}^2 &\leq \operatorname{{O}}(n \varepsilon).
\end{align}
Furthermore, we also know from \cref{lemma:average-clifford-relations} that
\begin{align}\label{eq:bound 2}
    \operatorname*{\mathbb{E}}_{x \sim \sigma_n} \norm{(A(x) \otimes I - I \otimes B(x))|{\psi}\rangle}^2 &\leq \operatorname{{O}}(\varepsilon)
\end{align}
Now, for any fixed choice of unit vectors $x_1,\dots,x_k \in S^{n-1}$, where $k \leq n$, we have
\begin{align*}
&\quad \norm*{\paren*{ \Phi_A A(x_1) \cdots A(x_k) \otimes I - (\gamma(x_1) \cdots \gamma(x_k) \otimes I) \Phi_A \otimes I } |{\psi}\rangle} \\
&\leq \norm*{\paren*{ \Phi_A A(x_1) \otimes B(x_k) \cdots B(x_2) - (\gamma(x_1) \cdots \gamma(x_k) \otimes I) \Phi_A \otimes I }|{\psi}\rangle}
+ \sum_{\ell=2}^k \norm*{\left( A(x_\ell) \otimes I - I \otimes B(x_\ell) \right) |{\psi}\rangle} \\
&\leq \sum_{\ell=1}^k \norm*{\left( \Phi_A A(x_\ell) \otimes I - (\gamma(x_\ell) \otimes I) \Phi_A \otimes I  \right) |{\psi}\rangle}
+ 2 \sum_{\ell=2}^k \norm*{\left(A(x_\ell) \otimes I - I \otimes B(x_\ell) \right) |{\psi}\rangle}
\end{align*}
by telescoping sums (first to swap all but the first $A(x_\ell)$ to $B(x_\ell)$, which reverses the order; then we successively replace $\Phi_A A(x_1)$ by $\gamma(x_1) \Phi_A$, swap $B(x_2)$ back to $A(x_2)$, and so forth until we are done).
Hence, using the Cauchy--Schwarz inequality and the linearity of expectation values,
\begin{align*}
&\quad \operatorname*{\mathbb{E}}_{R \in \mathrm{SO}(n)} \norm*{\Phi_A A(R x_1) \cdots A(R x_k) - \left(\gamma(R x_1) \cdots \gamma(R x_k) \otimes I\right) \Phi_A}_{\rho_A}^2 \\
&\leq 5k \operatorname*{\mathbb{E}}_{R \in \mathrm{SO}(n)}
\left(
\sum_{\ell=1}^k  \norm*{\Phi_A A(R x_\ell)- \left(\gamma(R x_\ell) \otimes I\right)\Phi_A}_{\rho_A}^2 + \sum_{\ell=2}^k  \norm*{\left(A(R x_\ell) \otimes I - I \otimes B(R x_\ell) \right) |{\psi}\rangle}^2 \right) \\
&\leq \operatorname{{O}}(n^3 \varepsilon).
\end{align*}
In the last step we used that each $R x_\ell$ is uniformly random on the sphere~$S^{n-1}$, so we can apply \cref{eq:bound 1,eq:bound 2}.

Finally, if $g \in \operatorname{Pin}(n)$ is Haar random then so is $h = \alpha_R^{-1}(g)$ for any fixed~$R$.
Thus, $h$ and $R$ are also independent.
Moreover, if $h = s c(x_1) \cdots c(x_k)$ then $g = s c(R x_1) \cdots c(R x_k)$.
As a consequence:
\begin{align*}
&\quad \operatorname*{\mathbb{E}}_{R \in \mathrm{SO}(n)} \operatorname*{\mathbb{E}}_{g \in \operatorname{Pin}(n)} \norm*{\Phi_A A_R(g) - \left( \Gamma(g) \otimes I \right) \Phi_A}_{\rho_A}^2 \\
&= \operatorname*{\mathbb{E}}_{h \in \operatorname{Pin}(n)} \operatorname*{\mathbb{E}}_{R \in \mathrm{SO}(n)} \left\lVert \Phi_A A(R x_1(h)) \cdots A(R x_{k(h)}(h)) - \left( \gamma(R x_1(h)) \cdots \gamma(R x_{k(h)}(h)) \otimes I \right) \Phi_A \right\rVert_{\rho_A}^2 \\
&\leq \operatorname{{O}}(n^3 \varepsilon).
\end{align*}
This is the desired inequality.

\label{thm:GH}
For any function $f \colon G \to \mathrm U(\mathcal H)$, the linear map
\begin{align*}
    V \colon \mathcal H \to \mathrm L^2(G, \mathcal H), \quad (V |{\psi}\rangle)(g) \coloneqq f(g) |{\psi}\rangle
\end{align*}
is an isometry.
Moreover, for every $h \in G$ and any state $\rho$ on $\mathcal H$:
\begin{align*}
  \norm{ V f(h) - R(h) V }_\rho^2 = \operatorname*{\mathbb{E}}_{g \in G} \norm{ f(g) f(h) - f(gh) }_\rho^2.
\end{align*}

\label{thm:GH irrep}
Let $\lambda \colon G \to \mathrm U(\mathcal H_\lambda)$ be a continuous irreducible representation with character~$\chi_\lambda$ and dimension~$d_\lambda$.
Let $f \colon G \to \mathrm{U}(\mathcal H)$ be a function such that $d_\lambda \operatorname*{\mathbb{E}}_{h \in G} \overline{\chi_\lambda(h)} f(gh) = f(g)$ for all~$g \in G$.
Then the image of the isometry $V$ from \cref{thm:GH} is in the $\lambda$-isotypical subspace of~$\mathrm L^2(G,\mathcal H)$, which using the Fourier transform of~$G$ identifies with $\operatorname{End}(\mathcal H_\lambda) \otimes \mathcal H \cong \mathcal H_\lambda \otimes \mathcal H_\lambda^* \otimes \mathcal H$.
Thus, the corresponding restriction
\begin{align*}
    V_\lambda \colon \mathcal H \to \operatorname{End}(\mathcal H_\lambda) \otimes \mathcal H \cong \mathcal H_\lambda \otimes \mathcal H_\lambda^* \otimes \mathcal H, \quad V_\lambda |{\psi}\rangle = \sqrt{d_\lambda} \operatorname*{\mathbb{E}}_{g \in G} \lambda(g)^\dagger \otimes f(g) |{\psi}\rangle
\end{align*}
is an isometry and it satisfies, for every $h \in G$ and any state $\rho$ on $\mathcal H$:
